<template>
  <section class="chat-container">
    <header class="chat-header"><div><p class="eyebrow">PRIVATE SIGNAL / CHAT</p><h1>Nói chuyện <em>nhẹ thôi.</em></h1><p>Tin nhắn hoạt động trong 60 phút rồi tự biến mất khỏi LuNu. Không chạm vào player đang phát.</p></div><div class="chat-status"><i :class="connectionClass"></i><span>{{ connectionLabel }}</span></div></header>
    <div class="chat-layout glass-panel">
      <aside class="conversation-panel"><div class="panel-heading"><div><span class="panel-kicker">INBOX</span><h2>Cuộc trò chuyện</h2></div><button type="button" class="refresh-btn" @click="loadConversations">↻</button></div><div v-if="loadingConversations" class="empty-chat">Đang tải...</div><div v-else-if="!conversations.length" class="empty-chat"><span>◌</span><strong>Chưa có cuộc trò chuyện</strong><small>Mở chat từ Friends Hub hoặc một Listening Room.</small></div><button v-for="conversation in conversations" v-else :key="conversation.id" type="button" class="conversation-row" :class="{ active: activeConversation?.id === conversation.id }" @click="openConversation(conversation)"><div class="conversation-avatar">{{ conversationLabel(conversation).slice(0, 1).toUpperCase() }}</div><div><strong>{{ conversationLabel(conversation) }}</strong><span>{{ conversation.kind === 'room' ? 'Phòng nghe' : 'Tin nhắn riêng' }}</span></div><b v-if="conversation.kind === 'room'">◉</b></button></aside>
      <main class="message-panel"><div v-if="!activeConversation" class="message-empty"><span>✦</span><h2>Chọn một cuộc trò chuyện</h2><p>Những đoạn hội thoại ngắn, riêng tư và tự hết hạn sau 60 phút.</p></div><template v-else><header class="message-heading"><div><span class="panel-kicker">{{ activeConversation.kind === 'room' ? 'ROOM CHAT' : 'DIRECT CHAT' }}</span><h2>{{ conversationLabel(activeConversation) }}</h2></div><span class="expiry-badge">TỰ XÓA · 60P</span></header><div ref="messageList" class="message-list"><div v-if="loadingMessages" class="empty-chat">Đang tải tin nhắn...</div><div v-else-if="!visibleMessages.length" class="empty-chat"><span>⌁</span><strong>Chưa có tin nhắn</strong><small>Gửi một lời chào để bắt đầu.</small></div><article v-for="message in visibleMessages" v-else :key="message.id" class="message-bubble" :class="{ mine: String(message.sender_id) === String(currentUserId) }"><div class="message-meta"><strong>{{ String(message.sender_id) === String(currentUserId) ? 'Bạn' : (message.sender?.display_name || message.sender?.username || 'Member') }}</strong><time>{{ formatTime(message.created_at) }} · còn {{ formatRemaining(message.expires_at) }}</time></div><p>{{ message.body }}</p><div class="message-actions"><button v-if="String(message.sender_id) === String(currentUserId)" type="button" @click="deleteMessage(message.id)">Xóa</button><button type="button" @click="reportMessage(message.id)">Report</button></div></article></div><form class="composer" @submit.prevent="sendMessage"><textarea v-model.trim="draft" maxlength="2000" rows="2" placeholder="Viết một điều đáng nhớ..." :disabled="sending" @keydown.enter.exact.prevent="sendMessage"></textarea><div class="composer-footer"><span>{{ draft.length }}/2000 · tự xóa sau 60 phút</span><button type="submit" :disabled="sending || !draft">{{ sending ? 'Đang gửi...' : 'Gửi →' }}</button></div></form></template></main>
    </div>
  </section>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue';
import { deleteChatMessage, getApiBaseUrl, getChatConversations, getChatMessages, reportChatMessage, sendChatMessage } from '../services/api';
import { authState } from '../store/appState';
import { chatSession, clearChatConversation, selectChatConversation } from '../store/chatSession';
import { useDialog } from '../composables/useDialog';
import { useToast } from '../composables/useToast';

const { confirmDialog, promptDialog } = useDialog();
const { showToast } = useToast();
const conversations = ref([]); const activeConversation = ref(null); const messages = ref([]); const draft = ref(''); const loadingConversations = ref(true); const loadingMessages = ref(false); const sending = ref(false); const connectionMode = ref('idle'); const now = ref(Date.now());
const messageList = ref(null); let socket = null; let reconnectTimer = null; let pollTimer = null; let ticker = null; let reconnectAttempt = 0;
const currentUserId = computed(() => authState.user?.id || '');
const visibleMessages = computed(() => messages.value.filter((message) => Date.parse(message.expires_at || '') > now.value));
const connectionLabel = computed(() => connectionMode.value === 'realtime' ? 'REALTIME · cùng instance' : connectionMode.value === 'fallback' ? 'FALLBACK · polling 4s' : 'READY');
const connectionClass = computed(() => connectionMode.value === 'realtime' ? 'online' : connectionMode.value === 'fallback' ? 'fallback' : 'idle');

const conversationLabel = (conversation) => conversation?.kind === 'room' ? (conversation.room?.name || 'Listening Room') : (conversation?.other_user?.display_name || conversation?.other_user?.username || 'Tin nhắn riêng');
const formatTime = (value) => { const date = new Date(value); return Number.isNaN(date.getTime()) ? '' : date.toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' }); };
const formatRemaining = (value) => { const seconds = Math.max(0, Math.floor((Date.parse(value || '') - now.value) / 1000)); return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`; };
const scrollToBottom = async () => { await nextTick(); if (messageList.value) messageList.value.scrollTop = messageList.value.scrollHeight; };
const upsertMessage = (message) => { if (!message?.id) return; const index = messages.value.findIndex((item) => String(item.id) === String(message.id)); if (index >= 0) messages.value.splice(index, 1, message); else messages.value.push(message); messages.value.sort((a, b) => Date.parse(a.created_at) - Date.parse(b.created_at)); scrollToBottom(); };
const removeMessage = (id) => { messages.value = messages.value.filter((message) => String(message.id) !== String(id)); };
const loadConversations = async () => { loadingConversations.value = true; try { const response = await getChatConversations(); conversations.value = response.items || []; const selected = conversations.value.find((item) => String(item.id) === String(chatSession.selectedId)); if (selected) await openConversation(selected); else if (activeConversation.value && !conversations.value.some((item) => item.id === activeConversation.value.id)) { activeConversation.value = null; clearChatConversation(); } } catch (error) { showToast(error.message || 'Không thể tải cuộc trò chuyện.', { type: 'warning' }); } finally { loadingConversations.value = false; } };
const loadMessages = async () => { if (!activeConversation.value) return; loadingMessages.value = true; try { const response = await getChatMessages(activeConversation.value.id); messages.value = response.items || []; await scrollToBottom(); } catch (error) { showToast(error.message || 'Không thể tải tin nhắn.', { type: 'error' }); } finally { loadingMessages.value = false; } };
const closeSocket = () => { if (socket) { socket.onclose = null; socket.close(); socket = null; } if (reconnectTimer) window.clearTimeout(reconnectTimer); reconnectTimer = null; };
const scheduleReconnect = () => { if (!activeConversation.value || reconnectTimer) return; reconnectAttempt += 1; const delay = Math.min(30000, 1000 * (2 ** Math.min(reconnectAttempt, 5))); reconnectTimer = window.setTimeout(() => { reconnectTimer = null; connectRealtime(); }, delay); };
const connectRealtime = () => { closeSocket(); if (!activeConversation.value) return; const base = getApiBaseUrl().replace(/^http/, 'ws'); socket = new WebSocket(`${base}/chat/ws?conversation_id=${encodeURIComponent(activeConversation.value.id)}`); socket.onopen = () => { connectionMode.value = 'fallback'; socket.send(JSON.stringify({ token: localStorage.getItem('lunu_access_token') || '' })); }; socket.onmessage = (event) => { try { const packet = JSON.parse(event.data); if (packet.event === 'ready') { reconnectAttempt = 0; connectionMode.value = 'realtime'; } if (packet.event === 'ping') socket.send(JSON.stringify({ type: 'pong' })); if (packet.event === 'pong') connectionMode.value = 'realtime'; if (packet.event === 'message_created') upsertMessage(packet.message); if (packet.event === 'message_deleted') removeMessage(packet.message_id); } catch (error) { console.warn('[LuNu chat] invalid realtime packet', error); } }; socket.onerror = () => { connectionMode.value = 'fallback'; }; socket.onclose = () => { if (activeConversation.value) { connectionMode.value = 'fallback'; scheduleReconnect(); } }; };
const pollMessages = async () => { if (!activeConversation.value) return; try { const response = await getChatMessages(activeConversation.value.id); for (const message of response.items || []) upsertMessage(message); messages.value = messages.value.filter((message) => Date.parse(message.expires_at || '') > now.value); } catch (error) { if (error.status !== 403 && error.status !== 404) console.warn('[LuNu chat] fallback poll failed', error); } };
const startFallback = () => { if (pollTimer) window.clearInterval(pollTimer); pollTimer = window.setInterval(pollMessages, 4000); };
const openConversation = async (conversation) => { if (!conversation?.id) return; activeConversation.value = conversation; selectChatConversation(conversation); messages.value = []; closeSocket(); reconnectAttempt = 0; connectionMode.value = 'fallback'; await loadMessages(); connectRealtime(); startFallback(); };
const sendMessage = async () => { if (!activeConversation.value || !draft.value || sending.value) return; const body = draft.value; sending.value = true; try { const response = await sendChatMessage(activeConversation.value.id, body); draft.value = ''; upsertMessage(response.message); showToast('Đã gửi. Tin nhắn sẽ tự xóa sau 60 phút.', { type: 'success', duration: 3000 }); } catch (error) { showToast(error.message || 'Không thể gửi tin nhắn.', { type: 'error' }); } finally { sending.value = false; } };
const deleteMessage = async (id) => { if (!await confirmDialog('Tin nhắn sẽ bị xóa khỏi cuộc trò chuyện cho mọi người.', { title: 'Xóa tin nhắn', confirmLabel: 'Xóa', danger: true })) return; try { await deleteChatMessage(id); removeMessage(id); showToast('Đã xóa tin nhắn.', { type: 'success' }); } catch (error) { showToast(error.message || 'Không thể xóa tin nhắn.', { type: 'error' }); } };
const reportMessage = async (id) => { const reason = await promptDialog('Lý do report tin nhắn này?', '', { title: 'Report tin nhắn', placeholder: 'Spam, quấy rối...', confirmLabel: 'Gửi report' }); if (!reason) return; try { await reportChatMessage(id, reason); showToast('Đã gửi report cho moderator.', { type: 'success' }); } catch (error) { showToast(error.message || 'Không thể report tin nhắn.', { type: 'error' }); } };

onMounted(async () => { ticker = window.setInterval(() => { now.value = Date.now(); messages.value = messages.value.filter((message) => Date.parse(message.expires_at || '') > now.value); }, 1000); await loadConversations(); });
onBeforeUnmount(() => { closeSocket(); if (pollTimer) window.clearInterval(pollTimer); if (ticker) window.clearInterval(ticker); });
</script>

<style scoped>
.chat-container { max-width: 1180px; margin: 0 auto; padding: 18px 0 92px; }.chat-header { display: flex; align-items: flex-end; justify-content: space-between; gap: 22px; padding: 32px 0 34px; }.eyebrow, .panel-kicker { color: var(--gold); font: 9px var(--font-mono); letter-spacing: 1.8px; }.chat-header h1 { margin-top: 12px; font: 500 clamp(40px, 5vw, 62px)/.95 var(--font-display); letter-spacing: -2px; }.chat-header h1 em { color: var(--gold); font-style: italic; }.chat-header p:last-child { max-width: 610px; margin-top: 15px; color: var(--text-sub); font-size: 12px; line-height: 1.65; }.chat-status { display: inline-flex; align-items: center; gap: 8px; padding: 10px 12px; border: 1px solid var(--hairline); border-radius: 12px; color: var(--text-sub); font: 9px var(--font-mono); letter-spacing: 1px; }.chat-status i { width: 7px; height: 7px; border-radius: 50%; background: var(--text-faint); }.chat-status i.online { background: var(--mint); box-shadow: 0 0 10px var(--mint); }.chat-status i.fallback { background: var(--gold); box-shadow: 0 0 10px var(--gold); }.chat-layout { display: grid; grid-template-columns: 290px minmax(0, 1fr); min-height: 620px; overflow: hidden; border-radius: 20px; }.conversation-panel { padding: 22px 14px; border-right: 1px solid var(--hairline); background: rgba(4,6,12,.28); }.panel-heading, .message-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }.panel-heading h2, .message-heading h2 { margin-top: 8px; color: var(--text-main); font: 500 23px var(--font-display); }.refresh-btn { border: 1px solid var(--hairline); border-radius: 8px; padding: 7px 9px; background: transparent; color: var(--text-sub); cursor: pointer; }.conversation-row { display: flex; align-items: center; width: 100%; gap: 10px; margin-top: 5px; padding: 10px 8px; border: 1px solid transparent; border-radius: 10px; background: transparent; color: var(--text-main); text-align: left; cursor: pointer; }.conversation-row:hover, .conversation-row.active { border-color: var(--hairline-soft); background: rgba(245,185,122,.08); }.conversation-avatar { display: grid; place-items: center; width: 36px; height: 36px; flex: 0 0 auto; border-radius: 12px; background: linear-gradient(135deg, var(--violet), var(--gold)); color: #171218; font: 800 11px var(--font-mono); }.conversation-row > div:nth-child(2) { display: flex; flex: 1; flex-direction: column; min-width: 0; }.conversation-row strong { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 10px; }.conversation-row span { margin-top: 4px; color: var(--text-faint); font: 8px var(--font-mono); }.conversation-row b { color: var(--gold); font-size: 10px; }.message-panel { display: flex; min-width: 0; flex-direction: column; padding: 23px 26px 20px; }.message-heading { padding-bottom: 17px; border-bottom: 1px solid var(--hairline-soft); }.expiry-badge { color: var(--gold-dim); font: 8px var(--font-mono); letter-spacing: 1px; }.message-list { display: flex; flex: 1; flex-direction: column; gap: 10px; max-height: 440px; overflow: auto; padding: 18px 4px; }.message-bubble { align-self: flex-start; max-width: min(80%, 540px); padding: 10px 13px; border: 1px solid var(--hairline-soft); border-radius: 12px 12px 12px 4px; background: rgba(255,255,255,.035); }.message-bubble.mine { align-self: flex-end; border-color: rgba(245,185,122,.2); border-radius: 12px 12px 4px 12px; background: rgba(245,185,122,.08); }.message-meta { display: flex; align-items: baseline; gap: 8px; }.message-meta strong { color: var(--gold-bright); font-size: 9px; }.message-meta time { color: var(--text-faint); font: 8px var(--font-mono); }.message-bubble p { margin-top: 6px; color: var(--text-main); font-size: 11px; line-height: 1.5; white-space: pre-wrap; overflow-wrap: anywhere; }.message-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 6px; opacity: 0; transition: opacity .2s; }.message-bubble:hover .message-actions, .message-bubble:focus-within .message-actions { opacity: 1; }.message-actions button { border: 0; background: transparent; color: var(--text-faint); cursor: pointer; font: 8px var(--font-mono); }.message-actions button:hover { color: var(--crimson); }.composer { margin-top: auto; padding-top: 12px; border-top: 1px solid var(--hairline-soft); }.composer textarea { width: 100%; box-sizing: border-box; resize: vertical; padding: 12px; border: 1px solid var(--hairline); border-radius: 11px; outline: 0; background: rgba(3,5,9,.34); color: var(--text-main); font: 11px/1.45 var(--font-body); }.composer textarea:focus { border-color: var(--gold); }.composer-footer { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: 8px; color: var(--text-faint); font: 8px var(--font-mono); }.composer-footer button { border: 0; border-radius: 9px; padding: 9px 14px; background: linear-gradient(135deg, var(--gold-bright), var(--gold)); color: #171218; cursor: pointer; font-size: 9px; font-weight: 800; }.composer-footer button:disabled { opacity: .55; cursor: not-allowed; }.empty-chat, .message-empty { display: grid; place-items: center; gap: 7px; min-height: 180px; color: var(--text-faint); text-align: center; }.empty-chat span, .message-empty > span { color: var(--gold); font-size: 25px; }.empty-chat strong, .message-empty h2 { color: var(--text-main); font: 500 17px var(--font-display); }.empty-chat small, .message-empty p { max-width: 250px; color: var(--text-faint); font-size: 9px; line-height: 1.5; }.message-empty { flex: 1; min-height: 450px; }
@media (max-width: 760px) { .chat-container { padding: 16px 0 102px; }.chat-header { align-items: flex-start; flex-direction: column; padding: 20px 0 25px; }.chat-status { align-self: flex-start; }.chat-layout { grid-template-columns: 1fr; min-height: auto; }.conversation-panel { max-height: 255px; overflow: auto; border-right: 0; border-bottom: 1px solid var(--hairline); }.message-panel { min-height: 520px; padding: 18px 14px 16px; }.message-list { max-height: 360px; }.message-bubble { max-width: 92%; }.message-meta { flex-wrap: wrap; }.message-actions { opacity: 1; }.composer-footer { align-items: flex-end; flex-direction: column; }.composer-footer button { width: 100%; padding: 12px; } }
</style>
